namespace merge {

__device__ __forceinline__ int make_warp_uniform(int x) {
    int result;
    asm volatile("shfl.sync.idx.b32 %0, %1, 0, 0x1F, 0xFFFFFFFF;"
                 : "=r"(result) : "r"(x));
    return result;
}

#define CAKE_SM120_DSV4_NVFP4_INF CUDART_INF_F
#define NUM_MAIN_STAGES 1
#define THREADS 256

#include <math_constants.h>

__device__ __forceinline__ float approx_exp2(float x) {
    float y;
    asm("ex2.approx.ftz.f32 %0, %1;" : "=f"(y) : "f"(x));
    return y;
}


__device__ __forceinline__ void mul_f32x2_inplace(float2* a, float2 b) {
    asm("mul.rn.f32x2 %0, %0, %1;"
        : "+l"(*(unsigned long long*)a) : "l"(*(unsigned long long*)&b));
}


// ex2_emulation_f32x2 defined in softmax_frag_exp2_cast helper (or standalone)


__global__ __launch_bounds__(256, 1) void
kernel_sm120_dsv4_nvfp4_sparse_mla_merge_h16(__nv_bfloat16* __restrict__ mid_out, float* __restrict__ mid_lse, float* __restrict__ attn_sink, __nv_bfloat16* __restrict__ output, float* __restrict__ out_lse, int num_splits, int scratch_split_stride, float lse_scale)
{
    const int tid = threadIdx.x;
    const int warp = make_warp_uniform(tid / 32);
    const int lane = tid % 32;


    const int bid = blockIdx.x;
    const int num_bids = gridDim.x;

    const int cta_rank = 0;

    // === Task calls (dependency order) ===
    int token = blockIdx.x;
    int head_local = tid >> 4;
    int part = tid & 15;
    if (head_local < ((1) ? 16 : 16)) {
        int h = blockIdx.y * 16 + head_local;
        int row = token * 16 + h;
        int lse_base = row * scratch_split_stride;
        float gmax = -1e+30f;
        for (int sidx = 0; sidx < num_splits; sidx++) {
            float _vec_load_0[1];
            {
                _vec_load_0[0] = *reinterpret_cast<const float*>(mid_lse + (lse_base + sidx));
            }
            float lse_s = _vec_load_0[0];
            float _fmax_0 = fmaxf(gmax, lse_s);
            gmax = _fmax_0;
        }
        float total = 0.0f;
        float o[32];
        o[0] = 0.0f;
        o[1] = 0.0f;
        o[2] = 0.0f;
        o[3] = 0.0f;
        o[4] = 0.0f;
        o[5] = 0.0f;
        o[6] = 0.0f;
        o[7] = 0.0f;
        o[8] = 0.0f;
        o[9] = 0.0f;
        o[10] = 0.0f;
        o[11] = 0.0f;
        o[12] = 0.0f;
        o[13] = 0.0f;
        o[14] = 0.0f;
        o[15] = 0.0f;
        o[16] = 0.0f;
        o[17] = 0.0f;
        o[18] = 0.0f;
        o[19] = 0.0f;
        o[20] = 0.0f;
        o[21] = 0.0f;
        o[22] = 0.0f;
        o[23] = 0.0f;
        o[24] = 0.0f;
        o[25] = 0.0f;
        o[26] = 0.0f;
        o[27] = 0.0f;
        o[28] = 0.0f;
        o[29] = 0.0f;
        o[30] = 0.0f;
        o[31] = 0.0f;
        if (gmax > -1e+29f) {
            for (int sidx_1 = 0; sidx_1 < num_splits; sidx_1++) {
                float _vec_load_1[1];
                {
                    _vec_load_1[0] = *reinterpret_cast<const float*>(mid_lse + (lse_base + sidx_1));
                }
                float lse_s2 = _vec_load_1[0];
                float _exp2_0 = approx_exp2(lse_s2 - gmax);
                float wgt = ((lse_s2 > -1e+29f) ? _exp2_0 : 0.0f);
                total = total + wgt;
                if (wgt > 0.0f) {
                    int src_base = (lse_base + sidx_1) * 512 + part * 32;
                    #pragma unroll
                    for (int v = 0; v < 4; v++) {
                        float _vec_load_2[8];
                        {
                            const uint4* _vptr_0 = reinterpret_cast<const uint4*>(mid_out + src_base + v * 8);
                            uint4 _vld_0[1];
                            #pragma unroll
                            for (int _blk = 0; _blk < 1; _blk++) {
                                _vld_0[_blk] = _vptr_0[_blk];
                                uint32_t* _vpairs_0 = reinterpret_cast<uint32_t*>(&_vld_0[_blk]);
                                #pragma unroll
                                for (int _pair = 0; _pair < 4; _pair++) {
                                    asm volatile(
                                        "{\n\t"
                                        "shl.b32 %0, %2, 16;\n\t"
                                        "and.b32 %1, %2, 0xffff0000;\n\t"
                                        "}\n"
                                        : "=f"((&_vec_load_2[0 + _blk * 8 + _pair * 2])[0]), "=f"((&_vec_load_2[0 + _blk * 8 + _pair * 2])[1])
                                        : "r"(_vpairs_0[_pair]));
                                }
                            }
                        }
                        #pragma unroll
                        for (int e = 0; e < 8; e++) {
                            o[v * 8 + e] = o[v * 8 + e] + _vec_load_2[e] * wgt;
                        }
                    }
                }
            }
        }
        float lse_out = -CAKE_SM120_DSV4_NVFP4_INF;
        if (total > 0.0f) {
            float _log2_0;
            asm volatile("lg2.approx.ftz.f32 %0, %1;" : "=f"(_log2_0) : "f"(total));
            lse_out = _log2_0 + gmax;
        }
        float osc = 1.0f;
        if ((unsigned long long)attn_sink != 0) {
            float _vec_load_3[1];
            {
                _vec_load_3[0] = *reinterpret_cast<const float*>(attn_sink + h);
            }
            float sink = _vec_load_3[0] * 1.4426950408889634f;
            float _fmax_1 = fmaxf(gmax, sink);
            float mx = _fmax_1;
            if (total <= 0.0f) {
                gmax = sink;
                total = 1.0f;
            } else {
                float _exp2_1 = approx_exp2(gmax - mx);
                osc = _exp2_1;
                float _exp2_2 = approx_exp2(sink - mx);
                total = total * osc + _exp2_2;
                gmax = mx;
            }
            float _log2_1;
            asm volatile("lg2.approx.ftz.f32 %0, %1;" : "=f"(_log2_1) : "f"(total));
            lse_out = _log2_1 + gmax;
        }
        float inv = ((total > 0.0f) ? osc / total : 0.0f);
        int dst_base = row * 512 + part * 32;
        #pragma unroll
        for (int v_1 = 0; v_1 < 4; v_1++) {
            {
                const float2 _prescale2_1 = {inv, inv};
                #if __CUDA_ARCH__ >= 1000
                #pragma unroll
                for (int _ps = 0; _ps < 4; _ps++)
                    mul_f32x2_inplace(&reinterpret_cast<float2*>(&o[v_1 * 8])[_ps], _prescale2_1);
                #else
                #pragma unroll
                for (int _ps = 0; _ps < 8; _ps++)
                    o[v_1 * 8 + _ps] *= inv;
                #endif
                __nv_bfloat162 _pk[4];
                _pk[0] = __floats2bfloat162_rn(o[v_1 * 8 + 0], o[v_1 * 8 + 1]);
                _pk[1] = __floats2bfloat162_rn(o[v_1 * 8 + 2], o[v_1 * 8 + 3]);
                _pk[2] = __floats2bfloat162_rn(o[v_1 * 8 + 4], o[v_1 * 8 + 5]);
                _pk[3] = __floats2bfloat162_rn(o[v_1 * 8 + 6], o[v_1 * 8 + 7]);
                *reinterpret_cast<uint4*>(&((__nv_bfloat16*)(output + (dst_base + v_1 * 8)))[0]) = *reinterpret_cast<uint4*>(&_pk[0]);
            }
        }
        if (part == 0) {
            float lse_scaled = ((lse_out == -1e+30f) ? lse_out : lse_out * lse_scale);
            *(reinterpret_cast<float*>(out_lse + row) + (0)) = lse_scaled;
        }
    }
}

